import { readdir, readFile, writeFile } from "node:fs/promises";
import { basename, resolve } from "node:path";

type Coverage = {
  unit: "transaction" | "fill";
  ground_truth: number;
  seen: number;
  missing: number;
  coverage_pct: number | null;
  observed_events_total: number;
};

type Latency = {
  samples: number;
  left_first: number;
  right_first: number;
  ties: number;
  left_first_pct: number;
  min_lead_ms: number;
  p25_lead_ms: number;
  median_lead_ms: number;
  mean_lead_ms: number;
  p75_lead_ms: number;
  p95_lead_ms: number;
  max_lead_ms: number;
};

type Summary = {
  chain_ground_truth: { transactions: number; fills: number };
  coverage: Record<string, Coverage>;
  latency: Record<string, Latency | null>;
  observations: Record<string, number | Record<string, number>>;
};

type Manifest = {
  provenance: { index_ts_sha256: string; analysis_ts_sha256: string };
  config: { duration_sec: number; struct_status: string };
  block_window: { from_block: number; to_block: number };
  lifecycle: Array<{ event: string }>;
  rpc_audit: Array<{ error?: string }>;
  struct_fill_index_reconciliation: { unmatched: number; index_order_hash_mismatches: number };
};

type Run = {
  name: string;
  summary: Summary;
  manifest: Manifest;
  samples: Map<string, number[]>;
};

function quantile(sorted: number[], q: number): number {
  const position = (sorted.length - 1) * q;
  const base = Math.floor(position);
  const fraction = position - base;
  return sorted[base] + fraction * ((sorted[base + 1] ?? sorted[base]) - sorted[base]);
}

function stats(values: number[]): Latency | null {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const left = sorted.filter((value) => value > 0).length;
  const right = sorted.filter((value) => value < 0).length;
  return {
    samples: sorted.length,
    left_first: left,
    right_first: right,
    ties: sorted.length - left - right,
    left_first_pct: (left / sorted.length) * 100,
    min_lead_ms: sorted[0],
    p25_lead_ms: quantile(sorted, 0.25),
    median_lead_ms: quantile(sorted, 0.5),
    mean_lead_ms: sorted.reduce((sum, value) => sum + value, 0) / sorted.length,
    p75_lead_ms: quantile(sorted, 0.75),
    p95_lead_ms: quantile(sorted, 0.95),
    max_lead_ms: sorted[sorted.length - 1],
  };
}

function parseSamples(csv: string): Map<string, number[]> {
  const result = new Map<string, number[]>();
  for (const line of csv.trim().split("\n").slice(1)) {
    const columns = line.split(",");
    const comparison = columns[0];
    const lead = Number(columns[10]);
    if (!comparison || !Number.isFinite(lead)) continue;
    const values = result.get(comparison) ?? [];
    values.push(lead);
    result.set(comparison, values);
  }
  return result;
}

async function loadRun(directory: string): Promise<Run> {
  const [summary, manifest, csv] = await Promise.all([
    readFile(resolve(directory, "summary.json"), "utf8"),
    readFile(resolve(directory, "manifest.json"), "utf8"),
    readFile(resolve(directory, "latency_samples.csv"), "utf8"),
  ]);
  return {
    name: basename(directory),
    summary: JSON.parse(summary) as Summary,
    manifest: JSON.parse(manifest) as Manifest,
    samples: parseSamples(csv),
  };
}

function percentage(numerator: number, denominator: number): number | null {
  return denominator ? (numerator / denominator) * 100 : null;
}

function fmtPercent(value: number | null): string {
  return value == null ? "n/a" : `${value.toFixed(2)}%`;
}

function fmtSeconds(milliseconds: number): string {
  return `${milliseconds >= 0 ? "+" : ""}${(milliseconds / 1_000).toFixed(3)} s`;
}

function latencyRow(label: string, value: Latency | null): string {
  if (!value) return `| ${label} | 0 | n/a | n/a | n/a |`;
  return `| ${label} | ${value.samples.toLocaleString()} | ${fmtSeconds(value.median_lead_ms)} | ${fmtSeconds(value.p95_lead_ms)} | ${value.left_first_pct.toFixed(2)}% |`;
}

async function main(): Promise<void> {
  const root = resolve(process.argv[2] ?? "results/full-suite-2026-08-01");
  const names = (await readdir(root)).filter((name) => name.startsWith("run-")).sort();
  if (!names.length) throw new Error(`No run directories found under ${root}`);
  const runs = await Promise.all(names.map((name) => loadRun(resolve(root, name))));
  runs.sort((a, b) => a.manifest.block_window.from_block - b.manifest.block_window.from_block);

  const issues: string[] = [];
  const sourceHashes = new Set(runs.map((run) =>
    `${run.manifest.provenance.index_ts_sha256}:${run.manifest.provenance.analysis_ts_sha256}`,
  ));
  if (sourceHashes.size !== 1) issues.push("Harness hashes differ across runs");
  for (let index = 1; index < runs.length; index++) {
    if (runs[index].manifest.block_window.from_block <= runs[index - 1].manifest.block_window.to_block) {
      issues.push(`${runs[index - 1].name} overlaps ${runs[index].name}`);
    }
  }
  for (const run of runs) {
    if (run.manifest.config.struct_status !== "all") issues.push(`${run.name}: Struct status was not all`);
    if (run.manifest.lifecycle.some(({ event }) => /error|failed|reconnect/i.test(event))) {
      issues.push(`${run.name}: socket lifecycle error/reconnect`);
    }
    if (run.manifest.rpc_audit.some(({ error }) => error)) issues.push(`${run.name}: RPC error`);
    if (run.manifest.struct_fill_index_reconciliation.unmatched) issues.push(`${run.name}: unmatched Struct fill`);
    if (run.manifest.struct_fill_index_reconciliation.index_order_hash_mismatches) {
      issues.push(`${run.name}: Struct index/order-hash mismatch`);
    }
  }

  const coverage: Record<string, Coverage> = {};
  for (const name of Object.keys(runs[0].summary.coverage)) {
    const values = runs.map((run) => run.summary.coverage[name]);
    const groundTruth = values.reduce((sum, value) => sum + value.ground_truth, 0);
    const seen = values.reduce((sum, value) => sum + value.seen, 0);
    coverage[name] = {
      unit: values[0].unit,
      ground_truth: groundTruth,
      seen,
      missing: groundTruth - seen,
      coverage_pct: percentage(seen, groundTruth),
      observed_events_total: values.reduce((sum, value) => sum + value.observed_events_total, 0),
    };
  }

  const pooled = new Map<string, number[]>();
  for (const run of runs) {
    for (const [comparison, values] of run.samples) {
      const current = pooled.get(comparison) ?? [];
      current.push(...values);
      pooled.set(comparison, current);
    }
  }
  const latency = Object.fromEntries([...pooled].map(([name, values]) => [name, stats(values)])) as Record<string, Latency | null>;
  for (const name of Object.keys(runs[0].summary.latency)) latency[name] ??= null;

  const transactions = runs.reduce((sum, run) => sum + run.summary.chain_ground_truth.transactions, 0);
  const fills = runs.reduce((sum, run) => sum + run.summary.chain_ground_truth.fills, 0);
  const suiteRuns = runs.map((run) => ({
    name: run.name,
    duration_sec: run.manifest.config.duration_sec,
    ...run.manifest.block_window,
    transactions: run.summary.chain_ground_truth.transactions,
    fills: run.summary.chain_ground_truth.fills,
    struct_pending_events: Number(run.summary.observations.struct_pending_events),
    confirmed_fill_latency: run.summary.latency.polynode_trade_vs_struct_confirmed_record,
    pending_vs_rtds_latency: run.summary.latency.polynode_pending_vs_rtds,
    rtds_coverage: run.summary.coverage.rtds_activity.coverage_pct,
  }));
  const suite = {
    generated_at: new Date().toISOString(),
    runs: suiteRuns,
    run_count: runs.length,
    scheduled_duration_sec: runs.reduce((sum, run) => sum + run.manifest.config.duration_sec, 0),
    chain_ground_truth: { transactions, fills },
    coverage,
    latency,
    integrity: { ok: issues.length === 0, issues, source_hashes: [...sourceHashes] },
  };

  const runRows = suiteRuns.map((run) => {
    const result = run.confirmed_fill_latency;
    return `| ${run.name} | ${run.duration_sec}s | ${run.from_block}-${run.to_block} | ${run.transactions.toLocaleString()} | ${run.fills.toLocaleString()} | ${run.struct_pending_events} | ${result ? fmtSeconds(result.median_lead_ms) : "n/a"} | ${result ? `${result.left_first_pct.toFixed(2)}%` : "n/a"} | ${fmtPercent(run.rtds_coverage)} |`;
  }).join("\n");

  const report = `# Exact Struct-methodology benchmark suite

Generated: ${suite.generated_at}

Five non-overlapping windows reproduce Struct's subscription and heartbeat implementation, while adding PolyNode and independent Polygon/Alchemy receipts. Positive latency means the left-hand path arrived first.

## Totals

- Core collection: ${suite.scheduled_duration_sec} seconds across ${suite.run_count} windows.
- Chain truth: ${transactions.toLocaleString()} transactions / ${fills.toLocaleString()} OrderFilled logs.
- Struct pending events: ${coverage.struct_pending.observed_events_total.toLocaleString()}.
- Integrity checks: ${suite.integrity.ok ? "passed" : `failed: ${issues.join("; ")}`}.

## Per-window results

| Run | Duration | Blocks | Transactions | Fills | Struct pending | Our confirmed-fill median lead | Our fills first | RTDS tx coverage |
|---|---:|---:|---:|---:|---:|---:|---:|---:|
${runRows}

## Pooled latency

| Left vs right | Samples | Median left lead | P95 left lead | Left first |
|---|---:|---:|---:|---:|
${latencyRow("PolyNode pending vs RTDS activity", latency.polynode_pending_vs_rtds)}
${latencyRow("PolyNode status_update vs RTDS activity", latency.polynode_status_update_vs_rtds)}
${latencyRow("PolyNode status_update vs Struct confirmed", latency.polynode_status_update_vs_struct_confirmed)}
${latencyRow("PolyNode confirmed fill vs Struct confirmed record", latency.polynode_trade_vs_struct_confirmed_record)}
${latencyRow("Struct confirmed vs RTDS activity", latency.struct_confirmed_vs_rtds)}
${latencyRow("PolyNode pending vs Struct pending", latency.polynode_pending_vs_struct_pending)}

## Confirmed completeness

| Path | Seen | Coverage | Missing |
|---|---:|---:|---:|
| PolyNode status_update transactions | ${coverage.polynode_status_update.seen.toLocaleString()}/${coverage.polynode_status_update.ground_truth.toLocaleString()} | ${fmtPercent(coverage.polynode_status_update.coverage_pct)} | ${coverage.polynode_status_update.missing} |
| PolyNode confirmed fills | ${coverage.polynode_trade_fill.seen.toLocaleString()}/${coverage.polynode_trade_fill.ground_truth.toLocaleString()} | ${fmtPercent(coverage.polynode_trade_fill.coverage_pct)} | ${coverage.polynode_trade_fill.missing} |
| Struct confirmed transactions | ${coverage.struct_confirmed_tx.seen.toLocaleString()}/${coverage.struct_confirmed_tx.ground_truth.toLocaleString()} | ${fmtPercent(coverage.struct_confirmed_tx.coverage_pct)} | ${coverage.struct_confirmed_tx.missing} |
| Struct confirmed records mapped to fills | ${coverage.struct_confirmed_record_fill.seen.toLocaleString()}/${coverage.struct_confirmed_record_fill.ground_truth.toLocaleString()} | ${fmtPercent(coverage.struct_confirmed_record_fill.coverage_pct)} | ${coverage.struct_confirmed_record_fill.missing} |
| RTDS activity transactions | ${coverage.rtds_activity.seen.toLocaleString()}/${coverage.rtds_activity.ground_truth.toLocaleString()} | ${fmtPercent(coverage.rtds_activity.coverage_pct)} | ${coverage.rtds_activity.missing} |

The RTDS results in this suite use Struct's literal uppercase \`PING\`. Polymarket's official client uses lowercase \`ping\`; an official-heartbeat control must be kept separate from these exact-reproduction results.
`;

  await Promise.all([
    writeFile(resolve(root, "suite-summary.json"), JSON.stringify(suite, null, 2) + "\n"),
    writeFile(resolve(root, "SUITE_REPORT.md"), report),
  ]);
  console.log(`Aggregated ${runs.length} runs into ${root}`);
  if (issues.length) process.exitCode = 2;
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});

