import assert from "node:assert/strict";
import test from "node:test";

import { analyze, type ChainFill, type NormalizedEvent } from "./analysis.js";

function event(
  sequence: number,
  source: NormalizedEvent["source"],
  path: NormalizedEvent["path"],
  txHash: string,
  logIndex?: number,
  tradeType?: string,
): NormalizedEvent {
  return {
    sequence,
    source,
    path,
    event_type: path,
    arrival_mono_ns: String(sequence * 1_000_000),
    arrival_wall_ms: sequence,
    tx_hash: txHash,
    log_index: logIndex,
    canonical_log_index: source === "struct" ? logIndex : undefined,
    trade_type: tradeType,
  };
}

const tx = `0x${"a".repeat(64)}`;
const fills: ChainFill[] = [
  {
    tx_hash: tx,
    log_index: 7,
    receipt_log_index: 1,
    block_number: 100,
    block_hash: `0x${"b".repeat(64)}`,
    address: `0x${"1".repeat(40)}`,
    version: "v1",
  },
  {
    tx_hash: tx,
    log_index: 9,
    receipt_log_index: 3,
    block_number: 100,
    block_hash: `0x${"b".repeat(64)}`,
    address: `0x${"1".repeat(40)}`,
    version: "v1",
  },
];

test("transaction coverage cannot conceal a missing fill", () => {
  const events: NormalizedEvent[] = [event(1, "struct", "confirmed", tx, 7, "OrderFilled")];
  const { analysis } = analyze(events, fills, { from_block: 100, to_block: 100 });

  assert.equal(analysis.coverage.struct_confirmed_tx.seen, 1);
  assert.equal(analysis.coverage.struct_confirmed_tx.coverage_pct, 100);
  assert.equal(analysis.coverage.struct_confirmed_fill.seen, 1);
  assert.equal(analysis.coverage.struct_confirmed_fill.coverage_pct, 50);
  assert.equal(analysis.missing.fills.struct_confirmed_fill[0].log_index, 9);
});

test("positive lead means the named left-hand source arrived first", () => {
  const events: NormalizedEvent[] = [
    event(1, "polynode", "confirmed", tx),
    event(4, "struct", "confirmed", tx, 7, "OrderFilled"),
  ];
  const { analysis, latencySamples } = analyze(events, fills.slice(0, 1), {
    from_block: 100,
    to_block: 100,
  });

  const stats = analysis.latency.polynode_status_update_vs_struct_confirmed;
  assert.ok(stats);
  assert.equal(stats.samples, 1);
  assert.equal(stats.median_lead_ms, 3);
  assert.equal(stats.left_first_pct, 100);
  assert.equal(
    latencySamples.find((sample) => sample.comparison === "polynode_status_update_vs_struct_confirmed")?.left_lead_ms,
    3,
  );
});

test("zero Struct pending events produces no fabricated latency statistic", () => {
  const events: NormalizedEvent[] = [event(1, "polynode", "pending", tx)];
  const { analysis } = analyze(events, fills.slice(0, 1), { from_block: 100, to_block: 100 });

  assert.equal(analysis.observations.struct_pending_events, 0);
  assert.equal(analysis.coverage.struct_pending.seen, 0);
  assert.equal(analysis.latency.polynode_pending_vs_struct_pending, null);
});

test("first confirmed fill is compared to RTDS at transaction granularity", () => {
  const events: NormalizedEvent[] = [
    event(2, "polynode", "confirmed_fill", tx, 7),
    event(5, "rtds", "activity", tx),
    event(7, "polynode", "confirmed_fill", tx, 9),
  ];
  const { analysis } = analyze(events, fills, { from_block: 100, to_block: 100 });

  const stats = analysis.latency.polynode_trade_tx_vs_rtds;
  assert.ok(stats);
  assert.equal(stats.samples, 1);
  assert.equal(stats.median_lead_ms, 3);
  assert.equal(stats.p90_lead_ms, 3);
  assert.equal(stats.p99_lead_ms, 3);
  assert.equal(stats.left_first_pct, 100);
});

test("confirmed status can be raced directly against Struct pending", () => {
  const events: NormalizedEvent[] = [
    event(2, "polynode", "confirmed", tx),
    event(35, "struct", "pending", tx),
  ];
  const { analysis } = analyze(events, fills.slice(0, 1), { from_block: 100, to_block: 100 });

  const stats = analysis.latency.polynode_status_update_vs_struct_pending;
  assert.ok(stats);
  assert.equal(stats.samples, 1);
  assert.equal(stats.median_lead_ms, 33);
  assert.equal(stats.left_first_pct, 100);
});

