export type Source = "struct" | "polynode" | "rtds";

export type EventPath =
  | "pending"
  | "confirmed"
  | "confirmed_fill"
  | "activity"
  | "settlement_other"
  | "control"
  | "other";

export type NormalizedEvent = {
  sequence: number;
  source: Source;
  path: EventPath;
  event_type: string;
  arrival_mono_ns: string;
  arrival_wall_ms: number;
  tx_hash?: string;
  log_index?: number;
  canonical_log_index?: number;
  block_number?: number;
  order_hash?: string;
  trade_type?: string;
  status?: string;
  source_reported_received_at_ms?: number;
};

export type ChainFill = {
  tx_hash: string;
  log_index: number;
  receipt_log_index: number;
  block_number: number;
  block_hash: string;
  address: string;
  order_hash?: string;
  version: "v1" | "v2";
};

export type BlockWindow = {
  from_block: number;
  to_block: number;
  from_block_hash?: string;
  to_block_hash?: string;
};

export type LatencyStats = {
  samples: number;
  left_first: number;
  right_first: number;
  ties: number;
  left_first_pct: number;
  min_lead_ms: number;
  p25_lead_ms: number;
  median_lead_ms: number;
  mean_lead_ms: number;
  p75_lead_ms: number;
  p90_lead_ms: number;
  p95_lead_ms: number;
  p99_lead_ms: number;
  max_lead_ms: number;
};

export type LatencySample = {
  comparison: string;
  join_key: string;
  tx_hash: string;
  log_index?: number;
  left: string;
  right: string;
  left_arrival_mono_ns: string;
  right_arrival_mono_ns: string;
  left_arrival_wall_ms: number;
  right_arrival_wall_ms: number;
  left_lead_ms: number;
};

type PathCoverage = {
  unit: "transaction" | "fill";
  ground_truth: number;
  seen: number;
  missing: number;
  coverage_pct: number | null;
  observed_events_total: number;
};

export type Analysis = {
  semantics: {
    latency_sign: string;
    pending: string;
    confirmed: string;
    fill_audit: string;
  };
  chain_ground_truth: {
    window: BlockWindow;
    transactions: number;
    fills: number;
    multi_fill_transactions: number;
    fills_by_version: Record<string, number>;
    fills_by_contract: Record<string, number>;
  };
  coverage: Record<string, PathCoverage>;
  latency: Record<string, LatencyStats | null>;
  missing: {
    transactions: Record<string, Array<{ tx_hash: string; block_number: number; fill_count: number }>>;
    fills: Record<string, ChainFill[]>;
  };
  observations: {
    total_events: number;
    events_by_source_path: Record<string, number>;
    struct_pending_events: number;
    struct_confirmed_events: number;
    polynode_pending_events: number;
    polynode_status_update_events: number;
    polynode_trade_events: number;
    rtds_activity_events: number;
  };
};

type FirstArrival = Pick<
  NormalizedEvent,
  "arrival_mono_ns" | "arrival_wall_ms" | "tx_hash" | "log_index"
>;

type PathSpec = {
  unit: "transaction" | "fill";
  match: (event: NormalizedEvent) => boolean;
};

const PATHS: Record<string, PathSpec> = {
  polynode_pending: {
    unit: "transaction",
    match: (event) => event.source === "polynode" && event.path === "pending",
  },
  polynode_status_update: {
    unit: "transaction",
    match: (event) => event.source === "polynode" && event.path === "confirmed",
  },
  polynode_trade_tx: {
    unit: "transaction",
    match: (event) => event.source === "polynode" && event.path === "confirmed_fill",
  },
  polynode_trade_fill: {
    unit: "fill",
    match: (event) => event.source === "polynode" && event.path === "confirmed_fill",
  },
  struct_pending: {
    unit: "transaction",
    match: (event) => event.source === "struct" && event.path === "pending",
  },
  struct_confirmed_tx: {
    unit: "transaction",
    match: (event) => event.source === "struct" && event.path === "confirmed",
  },
  struct_confirmed_fill: {
    unit: "fill",
    match: (event) =>
      event.source === "struct" &&
      event.path === "confirmed" &&
      event.trade_type === "OrderFilled" &&
      event.canonical_log_index != null,
  },
  struct_confirmed_record_fill: {
    unit: "fill",
    match: (event) =>
      event.source === "struct" &&
      event.path === "confirmed" &&
      (event.trade_type === "OrderFilled" || event.trade_type === "OrdersMatched") &&
      event.canonical_log_index != null,
  },
  rtds_activity: {
    unit: "transaction",
    match: (event) => event.source === "rtds" && event.path === "activity",
  },
};

function quantile(sorted: number[], q: number): number {
  if (sorted.length === 0) return Number.NaN;
  const position = (sorted.length - 1) * q;
  const base = Math.floor(position);
  const fraction = position - base;
  const lower = sorted[base];
  const upper = sorted[base + 1] ?? lower;
  return lower + fraction * (upper - lower);
}

function percentage(numerator: number, denominator: number): number | null {
  return denominator === 0 ? null : (numerator / denominator) * 100;
}

function fillKey(txHash: string, logIndex: number): string {
  return `${txHash}:${logIndex}`;
}

function earlier(candidate: FirstArrival, current: FirstArrival | undefined): boolean {
  if (!current) return true;
  return BigInt(candidate.arrival_mono_ns) < BigInt(current.arrival_mono_ns);
}

function firstByTransaction(events: NormalizedEvent[], match: PathSpec["match"]): Map<string, FirstArrival> {
  const result = new Map<string, FirstArrival>();
  for (const event of events) {
    if (!match(event) || !event.tx_hash) continue;
    if (earlier(event, result.get(event.tx_hash))) result.set(event.tx_hash, event);
  }
  return result;
}

function firstByFill(events: NormalizedEvent[], match: PathSpec["match"]): Map<string, FirstArrival> {
  const result = new Map<string, FirstArrival>();
  for (const event of events) {
    if (!match(event) || !event.tx_hash) continue;
    const canonicalIndex = event.source === "struct" ? event.canonical_log_index : event.log_index;
    if (canonicalIndex == null) continue;
    const key = fillKey(event.tx_hash, canonicalIndex);
    if (earlier(event, result.get(key))) result.set(key, event);
  }
  return result;
}

function latencyStats(samples: LatencySample[]): LatencyStats | null {
  if (samples.length === 0) return null;
  const leads = samples.map((sample) => sample.left_lead_ms).sort((a, b) => a - b);
  const leftFirst = leads.filter((lead) => lead > 0).length;
  const rightFirst = leads.filter((lead) => lead < 0).length;
  const ties = leads.length - leftFirst - rightFirst;
  return {
    samples: leads.length,
    left_first: leftFirst,
    right_first: rightFirst,
    ties,
    left_first_pct: (leftFirst / leads.length) * 100,
    min_lead_ms: leads[0],
    p25_lead_ms: quantile(leads, 0.25),
    median_lead_ms: quantile(leads, 0.5),
    mean_lead_ms: leads.reduce((sum, value) => sum + value, 0) / leads.length,
    p75_lead_ms: quantile(leads, 0.75),
    p90_lead_ms: quantile(leads, 0.90),
    p95_lead_ms: quantile(leads, 0.95),
    p99_lead_ms: quantile(leads, 0.99),
    max_lead_ms: leads[leads.length - 1],
  };
}

function compare(
  comparison: string,
  leftName: string,
  rightName: string,
  left: Map<string, FirstArrival>,
  right: Map<string, FirstArrival>,
  validKeys: Set<string>,
): { stats: LatencyStats | null; samples: LatencySample[] } {
  const samples: LatencySample[] = [];
  for (const key of validKeys) {
    const leftArrival = left.get(key);
    const rightArrival = right.get(key);
    if (!leftArrival || !rightArrival) continue;
    const leftNs = BigInt(leftArrival.arrival_mono_ns);
    const rightNs = BigInt(rightArrival.arrival_mono_ns);
    const txHash = key.includes(":") ? key.slice(0, key.lastIndexOf(":")) : key;
    const indexText = key.includes(":") ? key.slice(key.lastIndexOf(":") + 1) : undefined;
    samples.push({
      comparison,
      join_key: key,
      tx_hash: txHash,
      log_index: indexText == null ? undefined : Number(indexText),
      left: leftName,
      right: rightName,
      left_arrival_mono_ns: leftArrival.arrival_mono_ns,
      right_arrival_mono_ns: rightArrival.arrival_mono_ns,
      left_arrival_wall_ms: leftArrival.arrival_wall_ms,
      right_arrival_wall_ms: rightArrival.arrival_wall_ms,
      left_lead_ms: Number(rightNs - leftNs) / 1_000_000,
    });
  }
  return { stats: latencyStats(samples), samples };
}

function increment(record: Record<string, number>, key: string): void {
  record[key] = (record[key] ?? 0) + 1;
}

export function analyze(
  events: NormalizedEvent[],
  chainFills: ChainFill[],
  blockWindow: BlockWindow,
): { analysis: Analysis; latencySamples: LatencySample[] } {
  const chainFillByKey = new Map(chainFills.map((fill) => [fillKey(fill.tx_hash, fill.log_index), fill]));
  const chainFillKeys = new Set(chainFillByKey.keys());
  const txDetails = new Map<string, { block_number: number; fill_count: number }>();
  for (const fill of chainFills) {
    const current = txDetails.get(fill.tx_hash);
    if (current) current.fill_count++;
    else txDetails.set(fill.tx_hash, { block_number: fill.block_number, fill_count: 1 });
  }
  const chainTxKeys = new Set(txDetails.keys());

  const txMaps: Record<string, Map<string, FirstArrival>> = {};
  const fillMaps: Record<string, Map<string, FirstArrival>> = {};
  for (const [name, spec] of Object.entries(PATHS)) {
    if (spec.unit === "transaction") txMaps[name] = firstByTransaction(events, spec.match);
    else fillMaps[name] = firstByFill(events, spec.match);
  }

  const coverage: Record<string, PathCoverage> = {};
  const missingTransactions: Analysis["missing"]["transactions"] = {};
  const missingFills: Analysis["missing"]["fills"] = {};
  for (const [name, spec] of Object.entries(PATHS)) {
    const observedEvents = events.filter(spec.match).length;
    if (spec.unit === "transaction") {
      const map = txMaps[name];
      const missing = [...chainTxKeys]
        .filter((key) => !map.has(key))
        .map((tx_hash) => ({ tx_hash, ...txDetails.get(tx_hash)! }))
        .sort((a, b) => a.block_number - b.block_number || a.tx_hash.localeCompare(b.tx_hash));
      const seen = chainTxKeys.size - missing.length;
      coverage[name] = {
        unit: "transaction",
        ground_truth: chainTxKeys.size,
        seen,
        missing: missing.length,
        coverage_pct: percentage(seen, chainTxKeys.size),
        observed_events_total: observedEvents,
      };
      missingTransactions[name] = missing;
    } else {
      const map = fillMaps[name];
      const missing = [...chainFillKeys]
        .filter((key) => !map.has(key))
        .map((key) => chainFillByKey.get(key)!)
        .sort((a, b) => a.block_number - b.block_number || a.log_index - b.log_index);
      const seen = chainFillKeys.size - missing.length;
      coverage[name] = {
        unit: "fill",
        ground_truth: chainFillKeys.size,
        seen,
        missing: missing.length,
        coverage_pct: percentage(seen, chainFillKeys.size),
        observed_events_total: observedEvents,
      };
      missingFills[name] = missing;
    }
  }

  const comparisons: Array<{
    name: string;
    leftName: string;
    rightName: string;
    left: Map<string, FirstArrival>;
    right: Map<string, FirstArrival>;
    keys: Set<string>;
  }> = [
    {
      name: "polynode_pending_vs_polynode_status_update",
      leftName: "polynode_pending",
      rightName: "polynode_status_update",
      left: txMaps.polynode_pending,
      right: txMaps.polynode_status_update,
      keys: chainTxKeys,
    },
    {
      name: "struct_pending_vs_struct_confirmed",
      leftName: "struct_pending",
      rightName: "struct_confirmed",
      left: txMaps.struct_pending,
      right: txMaps.struct_confirmed_tx,
      keys: chainTxKeys,
    },
    {
      name: "polynode_pending_vs_struct_pending",
      leftName: "polynode_pending",
      rightName: "struct_pending",
      left: txMaps.polynode_pending,
      right: txMaps.struct_pending,
      keys: chainTxKeys,
    },
    {
      name: "polynode_status_update_vs_struct_confirmed",
      leftName: "polynode_status_update",
      rightName: "struct_confirmed",
      left: txMaps.polynode_status_update,
      right: txMaps.struct_confirmed_tx,
      keys: chainTxKeys,
    },
    {
      name: "polynode_status_update_vs_struct_pending",
      leftName: "polynode_status_update",
      rightName: "struct_pending",
      left: txMaps.polynode_status_update,
      right: txMaps.struct_pending,
      keys: chainTxKeys,
    },
    {
      name: "polynode_pending_vs_rtds",
      leftName: "polynode_pending",
      rightName: "rtds_activity",
      left: txMaps.polynode_pending,
      right: txMaps.rtds_activity,
      keys: chainTxKeys,
    },
    {
      name: "polynode_status_update_vs_rtds",
      leftName: "polynode_status_update",
      rightName: "rtds_activity",
      left: txMaps.polynode_status_update,
      right: txMaps.rtds_activity,
      keys: chainTxKeys,
    },
    {
      name: "polynode_trade_tx_vs_rtds",
      leftName: "polynode_first_confirmed_fill",
      rightName: "rtds_activity",
      left: txMaps.polynode_trade_tx,
      right: txMaps.rtds_activity,
      keys: chainTxKeys,
    },
    {
      name: "struct_pending_vs_rtds",
      leftName: "struct_pending",
      rightName: "rtds_activity",
      left: txMaps.struct_pending,
      right: txMaps.rtds_activity,
      keys: chainTxKeys,
    },
    {
      name: "struct_confirmed_vs_rtds",
      leftName: "struct_confirmed",
      rightName: "rtds_activity",
      left: txMaps.struct_confirmed_tx,
      right: txMaps.rtds_activity,
      keys: chainTxKeys,
    },
    {
      name: "polynode_trade_vs_struct_confirmed_record",
      leftName: "polynode_trade",
      rightName: "struct_confirmed_record",
      left: fillMaps.polynode_trade_fill,
      right: fillMaps.struct_confirmed_record_fill,
      keys: chainFillKeys,
    },
    {
      name: "polynode_trade_vs_struct_orderfilled_only",
      leftName: "polynode_trade",
      rightName: "struct_orderfilled",
      left: fillMaps.polynode_trade_fill,
      right: fillMaps.struct_confirmed_fill,
      keys: chainFillKeys,
    },
  ];

  const latency: Record<string, LatencyStats | null> = {};
  const latencySamples: LatencySample[] = [];
  for (const spec of comparisons) {
    const result = compare(spec.name, spec.leftName, spec.rightName, spec.left, spec.right, spec.keys);
    latency[spec.name] = result.stats;
    latencySamples.push(...result.samples);
  }

  const fillsByVersion: Record<string, number> = {};
  const fillsByContract: Record<string, number> = {};
  for (const fill of chainFills) {
    increment(fillsByVersion, fill.version);
    increment(fillsByContract, fill.address);
  }
  const eventsBySourcePath: Record<string, number> = {};
  for (const event of events) increment(eventsBySourcePath, `${event.source}:${event.path}`);

  const analysis: Analysis = {
    semantics: {
      latency_sign: "Each lead is right_arrival - left_arrival. Positive values mean the named left-hand path arrived first.",
      pending: "Struct pending is its documented received_at-without-block event; Polynode pending is settlement with status=pending.",
      confirmed: "Struct confirmed is a trade event carrying block; Polynode confirmed is status_update, as requested.",
      fill_audit: "Canonical confirmed-fill coverage is keyed by (transaction hash, block-global log index) against Polygon OrderFilled logs. Struct OrdersMatched records are also mapped to the corresponding taker OrderFilled by unique order hash and reported separately from strict event-type parity.",
    },
    chain_ground_truth: {
      window: blockWindow,
      transactions: chainTxKeys.size,
      fills: chainFillKeys.size,
      multi_fill_transactions: [...txDetails.values()].filter((detail) => detail.fill_count > 1).length,
      fills_by_version: fillsByVersion,
      fills_by_contract: fillsByContract,
    },
    coverage,
    latency,
    missing: { transactions: missingTransactions, fills: missingFills },
    observations: {
      total_events: events.length,
      events_by_source_path: eventsBySourcePath,
      struct_pending_events: events.filter(PATHS.struct_pending.match).length,
      struct_confirmed_events: events.filter(PATHS.struct_confirmed_tx.match).length,
      polynode_pending_events: events.filter(PATHS.polynode_pending.match).length,
      polynode_status_update_events: events.filter(PATHS.polynode_status_update.match).length,
      polynode_trade_events: events.filter(PATHS.polynode_trade_fill.match).length,
      rtds_activity_events: events.filter(PATHS.rtds_activity.match).length,
    },
  };

  return { analysis, latencySamples };
}

function fmtPct(value: number | null): string {
  return value == null ? "n/a" : `${value.toFixed(2)}%`;
}

function fmtMs(value: number): string {
  return `${value >= 0 ? "+" : ""}${value.toFixed(2)} ms`;
}

function coverageRow(label: string, value: PathCoverage): string {
  return `| ${label} | ${value.unit} | ${value.seen}/${value.ground_truth} | ${fmtPct(value.coverage_pct)} | ${value.missing} |`;
}

function latencyRow(label: string, stats: LatencyStats | null): string {
  if (!stats) return `| ${label} | 0 | n/a | n/a | n/a | n/a | n/a | n/a | n/a | n/a | n/a |`;
  return `| ${label} | ${stats.samples} | ${fmtMs(stats.min_lead_ms)} | ${fmtMs(stats.p25_lead_ms)} | ${fmtMs(stats.median_lead_ms)} | ${fmtMs(stats.p75_lead_ms)} | ${fmtMs(stats.p90_lead_ms)} | ${fmtMs(stats.p95_lead_ms)} | ${fmtMs(stats.p99_lead_ms)} | ${fmtMs(stats.max_lead_ms)} | ${stats.left_first_pct.toFixed(2)}% |`;
}

export function renderReport(
  analysis: Analysis,
  manifest: Record<string, unknown>,
): string {
  const coverage = analysis.coverage;
  const latency = analysis.latency;
  const config = manifest.config && typeof manifest.config === "object"
    ? manifest.config as Record<string, unknown>
    : {};
  const includeStruct = config.include_struct !== false;
  const structStatus = typeof config.struct_status === "string" ? config.struct_status : "all";
  const structPendingRequested = structStatus === "all" || structStatus === "pending";
  const structPendingBroken = includeStruct && structPendingRequested && analysis.observations.struct_pending_events === 0;
  const generatedAt = String(manifest.generated_at ?? new Date().toISOString());
  const window = analysis.chain_ground_truth.window;

  const findings: string[] = [];
  if (structPendingBroken) {
    findings.push(
      `- Struct emitted zero pending events under its documented \`status: "${structStatus}"\` subscription. Pending latency and pending coverage are therefore unavailable, not zero-latency wins or losses.`,
    );
  }
  const confirmedVsRtds = includeStruct ? latency.struct_confirmed_vs_rtds : null;
  if (confirmedVsRtds) {
    findings.push(
      `- Struct confirmed vs RTDS had ${confirmedVsRtds.samples} on-chain-overlap samples; Struct's median lead was ${fmtMs(confirmedVsRtds.median_lead_ms)} (positive means Struct first).`,
    );
  }
  const pnVsStruct = includeStruct ? latency.polynode_status_update_vs_struct_confirmed : null;
  if (pnVsStruct) {
    findings.push(
      `- Polynode status_update vs Struct confirmed had ${pnVsStruct.samples} samples; Polynode's median lead was ${fmtMs(pnVsStruct.median_lead_ms)} and arrived first in ${pnVsStruct.left_first_pct.toFixed(2)}%.`,
    );
  }
  findings.push(
    `- Independent Polygon logs contained ${analysis.chain_ground_truth.fills} OrderFilled fills across ${analysis.chain_ground_truth.transactions} transactions; ${analysis.chain_ground_truth.multi_fill_transactions} transactions contained multiple fills.`,
  );
  if (includeStruct) {
    const structRecords = coverage.struct_confirmed_record_fill;
    findings.push(
      `- Struct represented ${structRecords.seen}/${structRecords.ground_truth} on-chain fills when both of its documented record types are counted; strict OrderFilled-type parity was ${coverage.struct_confirmed_fill.seen}/${coverage.struct_confirmed_fill.ground_truth}.`,
    );
  }

  const structCoverageRows = includeStruct
    ? [
        coverageRow("Struct pending", coverage.struct_pending),
        coverageRow("Struct confirmed (tx)", coverage.struct_confirmed_tx),
        coverageRow("Struct confirmed OrderFilled only (strict type parity)", coverage.struct_confirmed_fill),
        coverageRow("Struct confirmed record (OrderFilled + mapped OrdersMatched)", coverage.struct_confirmed_record_fill),
      ].join("\n") + "\n"
    : "";
  const structLatencyRows = includeStruct
    ? [
        latencyRow("Struct pending vs Struct confirmed", latency.struct_pending_vs_struct_confirmed),
        latencyRow("Polynode pending vs Struct pending", latency.polynode_pending_vs_struct_pending),
        latencyRow("Polynode status_update vs Struct pending", latency.polynode_status_update_vs_struct_pending),
        latencyRow("Polynode status_update vs Struct confirmed", latency.polynode_status_update_vs_struct_confirmed),
        latencyRow("Struct pending vs RTDS", latency.struct_pending_vs_rtds),
        latencyRow("Struct confirmed vs RTDS", latency.struct_confirmed_vs_rtds),
        latencyRow("Polynode trade vs Struct confirmed record", latency.polynode_trade_vs_struct_confirmed_record),
        latencyRow("Polynode trade vs Struct OrderFilled only", latency.polynode_trade_vs_struct_orderfilled_only),
      ].join("\n") + "\n"
    : "";
  const structSemantics = includeStruct
    ? `- Struct: room \`polymarket_trades\`, filters \`{ "status": "${structStatus}", "subscribe_all": true }\`. The raw WebSocket callback is stamped before JSON parsing; the explicit envelope status is preserved, with Struct's documented \`received_at\`/\`block\` fields used only as a fallback.\n`
    : "";

  return `# Polynode vs ${includeStruct ? "Struct vs " : ""}Polymarket RTDS benchmark window

Generated: ${generatedAt}

## Result

${findings.join("\n")}

This is a same-vantage-point smoke test, not a universal latency claim. The raw observations and exact missing identifiers are retained so every conclusion can be independently checked.

## On-chain completeness

The denominator is Polygon \`OrderFilled\` logs in the fully observed block interval **${window.from_block} through ${window.to_block}**, inclusive. Transaction coverage answers "did the feed surface this transaction at least once?" Fill coverage is stricter and keys every execution by \`(transaction_hash, log_index)\`.

| Path | Unit | Seen | Coverage | Missing |
|---|---:|---:|---:|---:|
${coverageRow("Polynode pending settlement", coverage.polynode_pending)}
${coverageRow("Polynode status_update", coverage.polynode_status_update)}
${coverageRow("Polynode confirmed trade (tx)", coverage.polynode_trade_tx)}
${coverageRow("Polynode confirmed trade (fill)", coverage.polynode_trade_fill)}
${structCoverageRows}${coverageRow("RTDS activity", coverage.rtds_activity)}

## Latency

All arrivals were stamped inside one Node.js process using \`process.hrtime.bigint()\`. In every row, the number is **right arrival minus left arrival**; positive means the left-hand path arrived first. Only hashes/fills independently present in the on-chain denominator are eligible.

| Comparison (left vs right) | Samples | Min | P25 | P50 | P75 | P90 | P95 | P99 | Max | Left first |
|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|
${latencyRow("Polynode pending vs Polynode status_update", latency.polynode_pending_vs_polynode_status_update)}
${latencyRow("Polynode pending vs RTDS", latency.polynode_pending_vs_rtds)}
${latencyRow("Polynode status_update vs RTDS", latency.polynode_status_update_vs_rtds)}
${latencyRow("Polynode first confirmed fill vs RTDS", latency.polynode_trade_tx_vs_rtds)}
${structLatencyRows}

## Subscription semantics

${structSemantics}- Polynode pending: \`settlement\` events whose \`status\` is exactly \`pending\`.
- Polynode requested confirmed equivalent: \`status_update\`.
- Polynode exact confirmed-fill audit: \`trade\`, keyed by receipt \`log_index\`.
- Polymarket RTDS: \`activity/trades\` and \`activity/orders_matched\`, matching Struct's published harness.

## Boundary controls

Every socket was connected and acknowledged before warm-up. The denominator begins two future Polygon blocks after the warm-up tip, avoiding a partially observed first block. It ends two blocks behind the collection-end tip, and sockets remain open for a confirmation tail afterward. API keys are excluded from all artifacts; the manifest contains only one-way fingerprints.

## Reproduction and artifacts

- \`manifest.json\`: configuration, subscription acknowledgments, versions, key fingerprints, DNS, connection lifecycle, and anchored block window.
- \`events.ndjson\`: normalized timestamped observations.
- \`raw_frames.ndjson\`: parsed source frames/events for audit, with no credentials.
- \`rpc_logs.json\`: independent Polygon logs.
- \`latency_samples.csv\`: every matched latency sample, not only aggregates.
- \`missing.json\`: exact missing transaction hashes and fill identifiers.
- \`summary.json\`: machine-readable aggregate results.

Run \`npm test\` before collection and invoke the harness with credentials supplied only through environment variables. See \`README.md\` for the exact command.
`;
}

function csvCell(value: string | number | undefined): string {
  if (value == null) return "";
  const text = String(value);
  return /[",\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

export function latencySamplesCsv(samples: LatencySample[]): string {
  const columns: Array<keyof LatencySample> = [
    "comparison",
    "join_key",
    "tx_hash",
    "log_index",
    "left",
    "right",
    "left_arrival_mono_ns",
    "right_arrival_mono_ns",
    "left_arrival_wall_ms",
    "right_arrival_wall_ms",
    "left_lead_ms",
  ];
  return [
    columns.join(","),
    ...samples.map((sample) => columns.map((column) => csvCell(sample[column])).join(",")),
  ].join("\n") + "\n";
}

