    rtdsHeartbeat: (process.env.RTDS_HEARTBEAT as RtdsHeartbeat) ?? "struct-uppercase",
    rtdsSilenceReconnectSec: finiteSeconds(
      process.env.RTDS_SILENCE_RECONNECT_SEC ?? "0",
      "RTDS_SILENCE_RECONNECT_SEC",
    ),
    includeStruct: process.env.INCLUDE_STRUCT !== "false",
    out: process.env.OUT_DIR,
  };

  const argv = process.argv.slice(2);
  for (let index = 0; index < argv.length; index++) {
    const current = argv[index];
    const next = argv[index + 1];
    if (current === "--help") {
      printHelp();
      process.exit(0);
    } else if (current === "--duration-sec" && next) {
      args.durationSec = finiteSeconds(next, current);
      index++;
    } else if (current === "--warmup-sec" && next) {
      args.warmupSec = finiteSeconds(next, current);
      index++;
    } else if (current === "--tail-sec" && next) {
      args.tailSec = finiteSeconds(next, current);
      index++;
    } else if (current === "--struct-status" && next) {
      args.structStatus = next as StructStatus;
      index++;
    } else if (current === "--trade-types" && next) {
      args.tradeTypes = next.split(",").map((value) => value.trim()).filter(Boolean);
      index++;
    } else if (current === "--struct-ws" && next) {
      args.structWsBase = next;
      index++;
    } else if (current === "--polynode-ws" && next) {
      args.polynodeWsUrl = next;
      index++;
    } else if (current === "--rtds-url" && next) {
      args.rtdsUrl = next;
      index++;
    } else if (current === "--rtds-heartbeat" && next) {
      args.rtdsHeartbeat = next as RtdsHeartbeat;
      index++;
    } else if (current === "--rtds-silence-reconnect-sec" && next) {
      args.rtdsSilenceReconnectSec = finiteSeconds(next, current);
      index++;
    } else if (current === "--skip-struct") {
      args.includeStruct = false;
    } else if (current === "--out" && next) {
      args.out = next;
      index++;
    } else {
      throw new Error(`Unknown or incomplete option: ${current}`);
    }
  }

  if (!["pending", "confirmed", "all"].includes(args.structStatus)) {
    throw new Error("--struct-status must be pending, confirmed, or all");
  }
  if (!["struct-uppercase", "polymarket-lowercase"].includes(args.rtdsHeartbeat)) {
    throw new Error("--rtds-heartbeat must be struct-uppercase or polymarket-lowercase");
  }
  if (args.includeStruct && !args.structApiKey) throw new Error("Missing STRUCT_API_KEY");
  if (!args.polynodeApiKey) throw new Error("Missing POLYNODE_API_KEY");
  if (!args.polygonRpcUrl) throw new Error("Missing POLYGON_RPC_URL");
  if (args.durationSec < 10) throw new Error("--duration-sec must be at least 10 seconds");
  return args;
}

function now(): Stamp {
  return { monoNs: process.hrtime.bigint().toString(), wallMs: Date.now() };
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolvePromise) => setTimeout(resolvePromise, ms));
}

function normalizeHash(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const text = value.trim().toLowerCase();
  if (!text) return undefined;
  return text.startsWith("0x") ? text : `0x${text}`;
}

function numeric(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value !== "string" || value.trim() === "") return undefined;
  const parsed = value.startsWith("0x") ? Number.parseInt(value, 16) : Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function isObject(value: unknown): value is Record<string, unknown> {
  return value != null && typeof value === "object" && !Array.isArray(value);
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function safeUrl(value: string): string {
  const url = new URL(value);
  url.username = "";
  url.password = "";
  url.search = "";
  url.hash = "";
  if (url.pathname.includes("/v2/")) url.pathname = `${url.pathname.slice(0, url.pathname.indexOf("/v2/") + 4)}<redacted>`;
  return url.toString();
}

function fingerprint(secret: string): string {
  return `sha256:${createHash("sha256").update(secret).digest("hex").slice(0, 16)}`;
}

function hexBlock(block: number): string {
  return `0x${block.toString(16)}`;
}

async function linuxMemorySnapshot(): Promise<Record<string, number | string>> {
  const sampledAt = new Date().toISOString();
  try {
    const text = await readFile("/proc/meminfo", "utf8");
    const values = new Map<string, number>();
    for (const line of text.split("\n")) {
      const match = line.match(/^([A-Za-z_()]+):\s+(\d+)\s+kB$/);
      if (match) values.set(match[1], Number(match[2]) * 1024);
    }
    return {
      sampled_at: sampledAt,
      mem_total_bytes: values.get("MemTotal") ?? 0,
      mem_available_bytes: values.get("MemAvailable") ?? 0,
      swap_total_bytes: values.get("SwapTotal") ?? 0,
      swap_free_bytes: values.get("SwapFree") ?? 0,
    };
  } catch (error) {
    return { sampled_at: sampledAt, error: errorText(error) };
  }
}

class Recorder {
  readonly events: NormalizedEvent[] = [];
  readonly lifecycle: LifecycleEvent[] = [];
  private sequence = 0;
  private readonly rawFrameStream: WriteStream;
  private rawFrameWriteError: Error | undefined;
  private rawFramesFinished = false;
  rawFramesWritten = 0;
  rawFrameBackpressureWrites = 0;

  constructor(rawFramePath: string) {
    this.rawFrameStream = createWriteStream(rawFramePath, {
      flags: "wx",
      highWaterMark: 1024 * 1024,
    });
    this.rawFrameStream.on("error", (error) => {
      this.rawFrameWriteError = error;
    });
  }

  frame(source: Source, parsed: unknown, stamp = now()): void {
    if (this.rawFramesFinished) throw new Error("raw frame stream is already closed");
    const frame: RawFrame = {
      sequence: ++this.sequence,
      source,
      arrival_mono_ns: stamp.monoNs,
      arrival_wall_ms: stamp.wallMs,
      parsed,
    };
    this.rawFramesWritten++;
    if (!this.rawFrameStream.write(`${JSON.stringify(frame)}\n`)) {
      this.rawFrameBackpressureWrites++;
    }
  }

  event(
    source: Source,
    path: EventPath,
    eventType: string,
    fields: Partial<Omit<NormalizedEvent, "sequence" | "source" | "path" | "event_type" | "arrival_mono_ns" | "arrival_wall_ms">>,
    stamp = now(),
  ): void {
    this.events.push({
      sequence: ++this.sequence,
      source,
      path,
      event_type: eventType,
      arrival_mono_ns: stamp.monoNs,
      arrival_wall_ms: stamp.wallMs,
      ...fields,
    });
  }

  life(source: LifecycleEvent["source"], event: string, detail?: unknown): void {
    this.lifecycle.push({ source, event, wall_ms: Date.now(), ...(detail === undefined ? {} : { detail }) });
  }

  async finishRawFrames(): Promise<void> {
    if (this.rawFramesFinished) {
      if (this.rawFrameWriteError) throw this.rawFrameWriteError;
      return;
    }
    this.rawFramesFinished = true;
    await new Promise<void>((resolvePromise, rejectPromise) => {
      const onError = (error: Error) => rejectPromise(error);
      this.rawFrameStream.once("error", onError);
      this.rawFrameStream.end(() => {
        this.rawFrameStream.off("error", onError);
        if (this.rawFrameWriteError) rejectPromise(this.rawFrameWriteError);
        else resolvePromise();
      });
    });
  }
}

class RpcClient {
  readonly audit: RpcAudit[] = [];
  private id = 0;

  constructor(private readonly url: string, private readonly recorder: Recorder) {}

  async call<T>(method: string, params: unknown[]): Promise<T> {
    let lastError: unknown;
    for (let attempt = 1; attempt <= 3; attempt++) {
      const started = performance.now();
      const audit: RpcAudit = {
        method,
        params,
        started_at: new Date().toISOString(),
        duration_ms: 0,
      };
      try {
        const response = await fetch(this.url, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ jsonrpc: "2.0", id: ++this.id, method, params }),
          signal: AbortSignal.timeout(20_000),
        });
        audit.http_status = response.status;
        const body = (await response.json()) as { result?: T; error?: { message?: string } };
        audit.duration_ms = performance.now() - started;
        if (!response.ok || body.error || body.result === undefined) {
          throw new Error(body.error?.message ?? `HTTP ${response.status}`);
        }
        if (Array.isArray(body.result)) audit.result_count = body.result.length;
        this.audit.push(audit);
        return body.result;
      } catch (error) {
        audit.duration_ms = performance.now() - started;
        audit.error = errorText(error);
        this.audit.push(audit);
        lastError = error;
        this.recorder.life("rpc", "retry", { method, attempt, error: audit.error });
        if (attempt < 3) await sleep(250 * attempt);
      }
    }
    throw new Error(`RPC ${method} failed after retries: ${errorText(lastError)}`);
  }

  async blockNumber(): Promise<number> {
    const value = await this.call<string>("eth_blockNumber", []);
    const parsed = numeric(value);
    if (parsed == null) throw new Error(`Invalid eth_blockNumber response: ${String(value)}`);
    return parsed;
  }

  async batch<T>(method: string, parameterSets: unknown[][], batchSize = 100): Promise<T[]> {
    const allResults: T[] = [];
    for (let offset = 0; offset < parameterSets.length; offset += batchSize) {
      const chunk = parameterSets.slice(offset, offset + batchSize);
      let lastError: unknown;
      let completed = false;
      for (let attempt = 1; attempt <= 3 && !completed; attempt++) {
        const started = performance.now();
        const requests = chunk.map((params) => ({ jsonrpc: "2.0", id: ++this.id, method, params }));
        const audit: RpcAudit = {
          method: `${method}[batch]`,
          params: [{ offset, batch_size: chunk.length }],
          started_at: new Date().toISOString(),
          duration_ms: 0,
        };
        try {
          const response = await fetch(this.url, {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify(requests),
            signal: AbortSignal.timeout(30_000),
          });
          audit.http_status = response.status;
          const body = (await response.json()) as Array<{
            id: number;
            result?: T;
            error?: { message?: string };
          }>;
          audit.duration_ms = performance.now() - started;
          if (!response.ok || !Array.isArray(body)) throw new Error(`HTTP ${response.status} or invalid batch response`);
          const byId = new Map(body.map((entry) => [entry.id, entry]));
          const ordered = requests.map((request) => {
            const entry = byId.get(request.id);
            if (!entry || entry.error || entry.result === undefined) {
              throw new Error(entry?.error?.message ?? `Missing batch response id ${request.id}`);
            }
            return entry.result;
          });
          audit.result_count = ordered.length;
          this.audit.push(audit);
          allResults.push(...ordered);
          completed = true;
        } catch (error) {
          audit.duration_ms = performance.now() - started;
          audit.error = errorText(error);
          this.audit.push(audit);
          lastError = error;
          this.recorder.life("rpc", "batch_retry", { method, offset, attempt, error: audit.error });
          if (attempt < 3) await sleep(250 * attempt);
        }
      }
      if (!completed) throw new Error(`RPC batch ${method} failed after retries: ${errorText(lastError)}`);
    }
    return allResults;
  }
}

function connectRtds(args: Args, recorder: Recorder): Closable & { ready: Promise<unknown> } {
  let socket: WebSocketImpl | undefined;
  let heartbeatTimer: ReturnType<typeof setTimeout> | undefined;
  let watchdogTimer: ReturnType<typeof setInterval> | undefined;
  let reconnectTimer: ReturnType<typeof setTimeout> | undefined;
  let settled = false;
  let stopped = false;
  let attempt = 0;
  let lastActivityWallMs = 0;
  let connectedWallMs = 0;
  let resolveReady!: (value: unknown) => void;
  let rejectReady!: (reason: unknown) => void;
  const request = {
    action: "subscribe",
    subscriptions: [
      { topic: "activity", type: "trades" },
      { topic: "activity", type: "orders_matched" },
    ],
  };
  const ready = new Promise<unknown>((resolvePromise, rejectPromise) => {
    resolveReady = resolvePromise;
    rejectReady = rejectPromise;
  });
  const initialTimeout = setTimeout(() => {
    if (!settled) {
      settled = true;
      rejectReady(new Error("RTDS connection timed out"));
    }
  }, 12_000);

  const clearSocketTimers = () => {
    if (heartbeatTimer) clearTimeout(heartbeatTimer);
    if (watchdogTimer) clearInterval(watchdogTimer);
    heartbeatTimer = undefined;
    watchdogTimer = undefined;
  };

  const scheduleReconnect = () => {
    if (stopped || reconnectTimer) return;
    reconnectTimer = setTimeout(() => {
      reconnectTimer = undefined;
      openSocket();
    }, 250);
  };

  const openSocket = () => {
    if (stopped) return;
    attempt++;
    const current = new WebSocketImpl(args.rtdsUrl);
    socket = current;
    const sendOfficialHeartbeat = () => {
      if (current.readyState === WebSocketImpl.OPEN) current.send("ping");
    };

    current.on("open", () => {
      if (current !== socket) return;
      connectedWallMs = Date.now();
      lastActivityWallMs = connectedWallMs;
      recorder.life("rtds", attempt === 1 ? "connected" : "reconnected", { attempt });
      current.send(JSON.stringify(request));
      recorder.life("rtds", "subscription_sent", { attempt, ...request });
      if (args.rtdsHeartbeat === "struct-uppercase") {
        heartbeatTimer = setInterval(() => {
          if (current.readyState === WebSocketImpl.OPEN) current.send("PING");
        }, RTDS_PING_INTERVAL_MS);
      } else {
        sendOfficialHeartbeat();
        heartbeatTimer = setInterval(sendOfficialHeartbeat, RTDS_PING_INTERVAL_MS);
      }
      if (args.rtdsSilenceReconnectSec > 0) {
        watchdogTimer = setInterval(() => {
          if (current !== socket || current.readyState !== WebSocketImpl.OPEN) return;
          const quietMs = Date.now() - lastActivityWallMs;
          if (quietMs < args.rtdsSilenceReconnectSec * 1_000) return;
          recorder.life("rtds", "silence_reconnect", {
            attempt,
            quiet_ms: quietMs,
            connected_ms: Date.now() - connectedWallMs,
          });
          clearSocketTimers();
          current.terminate();
        }, 1_000);
      }
      if (!settled) {
        settled = true;
        clearTimeout(initialTimeout);
        resolveReady({
          sent: request,
          protocol_has_no_required_ack: true,
          heartbeat: args.rtdsHeartbeat,
          silence_reconnect_sec: args.rtdsSilenceReconnectSec,
        });
      }
    });
    current.on("message", (raw: RawData) => {
      if (current !== socket) return;
      const stamp = now();
      const text = raw.toString();
      if (text === "PONG") return;
      let parsed: unknown;
      try {
        parsed = JSON.parse(text);
      } catch {
        recorder.frame("rtds", text, stamp);
        return;
      }
      recorder.frame("rtds", parsed, stamp);
      if (!isObject(parsed) || parsed.topic !== "activity") return;
      if (parsed.type !== "trades" && parsed.type !== "orders_matched") return;
      lastActivityWallMs = stamp.wallMs;
      const payloads = Array.isArray(parsed.payload) ? parsed.payload : [parsed.payload];
      for (const rawPayload of payloads) {
        if (!isObject(rawPayload)) continue;
        recorder.event(
          "rtds",
          "activity",
          String(parsed.type),
          {
            tx_hash: normalizeHash(rawPayload.transactionHash ?? rawPayload.transaction_hash ?? rawPayload.hash),
            trade_type: String(parsed.type),
          },
          stamp,
        );
      }
    });
    current.on("error", (error) => {
      recorder.life("rtds", "error", { attempt, message: error.message });
      if (!settled) {
        settled = true;
        clearTimeout(initialTimeout);
        rejectReady(error);
      }
    });
    current.on("close", (code, reason) => {
      recorder.life("rtds", "disconnected", { attempt, code, reason: reason.toString(), stopped });
      if (current === socket) {
        clearSocketTimers();
        scheduleReconnect();
      }
    });
  };

  openSocket();

  return {
    ready,
    close: () => {
      stopped = true;
      clearTimeout(initialTimeout);
      clearSocketTimers();
      if (reconnectTimer) clearTimeout(reconnectTimer);
      try { socket?.close(); } catch { /* noop */ }
    },
  };
}

function connectStruct(args: Args, recorder: Recorder): Closable & { ready: Promise<unknown> } {
  const url = new URL(args.structWsBase);
  url.protocol = url.protocol === "http:" ? "ws:" : "wss:";
  url.pathname = `${url.pathname.replace(/\/+$/, "")}/ws`;
  url.searchParams.set("api-key", args.structApiKey);
  const filters: Record<string, unknown> = { status: args.structStatus, subscribe_all: true };
  if (args.tradeTypes?.length) filters.trade_types = args.tradeTypes;
  const socket = new WebSocketImpl(url.toString());
  let resolved = false;
  let stopped = false;
  let pingTimer: ReturnType<typeof setInterval> | undefined;
  let resolveReady!: (value: unknown) => void;
  let rejectReady!: (reason: unknown) => void;
  const ready = new Promise<unknown>((resolvePromise, rejectPromise) => {
    resolveReady = resolvePromise;
    rejectReady = rejectPromise;
  });
  const timeout = setTimeout(() => {
    if (!resolved) {
      resolved = true;
      rejectReady(new Error("Struct subscription acknowledgment timed out"));
    }
  }, 12_000);

  socket.on("open", () => {
    recorder.life("struct", "connected", { transport: "raw_websocket" });
    const roomId = "polymarket_trades";
    socket.send(JSON.stringify({ type: "join_room", payload: { room_id: roomId } }));
    socket.send(JSON.stringify({
      type: "room_message",
      payload: { room_id: roomId, message: { action: "subscribe", ...filters } },
    }));
    recorder.life("struct", "subscription_sent", { room: roomId, requested: filters });
    pingTimer = setInterval(() => {
      if (socket.readyState === WebSocketImpl.OPEN) socket.send(JSON.stringify({ type: "ping" }));
    }, 30_000);
  });
  socket.on("message", (raw: RawData) => {
    const stamp = now();
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw.toString());
    } catch {
      recorder.frame("struct", raw.toString(), stamp);
      recorder.life("struct", "parse_error");
      return;
    }
    if (!isObject(parsed)) {
      recorder.frame("struct", parsed, stamp);
      return;
    }
    if (parsed.type === "pong") return;
    recorder.frame("struct", parsed, stamp);
    if (
      typeof parsed.type === "string" &&
      (parsed.type === "subscribed" || parsed.type.endsWith("_subscribe_response")) &&
      parsed.room_id === "polymarket_trades" &&
      !resolved
    ) {
      resolved = true;
      clearTimeout(timeout);
      recorder.life("struct", "subscribed", { requested: filters, acknowledged: parsed.data });
      resolveReady(parsed.data);
      return;
    }
    if (parsed.type !== "trade_stream_update" || !isObject(parsed.data)) return;
    const event = parsed.data;
    const envelopeStatus = typeof parsed.status === "string" ? parsed.status.toLowerCase() : undefined;
    const isPending = envelopeStatus === "pending" || (event.received_at != null && event.block == null);
    recorder.event(
      "struct",
      isPending ? "pending" : "confirmed",
      "trade_stream_update",
      {
        tx_hash: normalizeHash(event.hash),
        log_index: numeric(event.log_index),
        block_number: numeric(event.block),
        order_hash: normalizeHash(event.order_hash),
        trade_type: typeof event.trade_type === "string" ? event.trade_type : undefined,
        status: envelopeStatus ?? (isPending ? "pending" : "confirmed"),
        source_reported_received_at_ms: numeric(event.received_at),
      },
      stamp,
    );
  });
  socket.on("error", (error) => {
    recorder.life("struct", "error", { message: error.message });
    if (!resolved) {
      resolved = true;
      clearTimeout(timeout);
      rejectReady(error);
    }
  });
  socket.on("close", (code, reason) => {
    if (pingTimer) clearInterval(pingTimer);
    recorder.life("struct", "disconnected", { code, reason: reason.toString(), stopped });
    if (!resolved) {
      resolved = true;
      clearTimeout(timeout);
      rejectReady(new Error(`Struct socket closed before acknowledgment: ${code}`));
    }
  });

  return {
    ready,
    close: () => {
      stopped = true;
      clearTimeout(timeout);
      if (pingTimer) clearInterval(pingTimer);
      try { socket.close(1000, "client disconnect"); } catch { /* noop */ }
    },
  };
}

function connectPolynode(args: Args, recorder: Recorder): Closable & { ready: Promise<unknown> } {
  const url = new URL(args.polynodeWsUrl);
  url.searchParams.set("key", args.polynodeApiKey);
  const socket = new WebSocketImpl(url.toString());
  let resolved = false;
  let resolveReady: (value: unknown) => void;
  let rejectReady: (reason: unknown) => void;
  const ready = new Promise<unknown>((resolvePromise, rejectPromise) => {
    resolveReady = resolvePromise;
    rejectReady = rejectPromise;
  });
  const timeout = setTimeout(() => {
    if (!resolved) {
      resolved = true;
      rejectReady(new Error("Polynode subscription acknowledgment timed out"));
    }
  }, 12_000);

  socket.on("open", () => {
    recorder.life("polynode", "connected");
    const request = { action: "subscribe", type: "trades" };
    socket.send(JSON.stringify(request));
    recorder.life("polynode", "subscription_sent", request);
  });
  socket.on("message", (raw: RawData) => {
    const stamp = now();
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw.toString());
    } catch {
      recorder.frame("polynode", raw.toString(), stamp);
      return;
    }
    recorder.frame("polynode", parsed, stamp);
    if (!isObject(parsed)) return;
    if (parsed.type === "subscribed" && parsed.subscription_type === "trades" && !resolved) {
      resolved = true;
      clearTimeout(timeout);
      recorder.life("polynode", "subscribed", parsed);
      resolveReady(parsed);
    }
    const candidates = Array.isArray(parsed.events) ? parsed.events : [parsed];
    for (const candidate of candidates) {
      if (!isObject(candidate)) continue;
      const data = isObject(candidate.data) ? candidate.data : candidate;
      const eventType = typeof data.event_type === "string" ? data.event_type : undefined;
      if (!eventType) continue;
      const fields = {
        tx_hash: normalizeHash(data.tx_hash),
        log_index: numeric(data.log_index),
        block_number: numeric(data.block_number),
        order_hash: normalizeHash(data.order_hash),
        status: typeof data.status === "string" ? data.status.toLowerCase() : undefined,
      };
      if (eventType === "settlement") {
        recorder.event(
          "polynode",
          fields.status === "pending" ? "pending" : "settlement_other",
          eventType,
          fields,
          stamp,
        );
      } else if (eventType === "status_update") {
        recorder.event("polynode", "confirmed", eventType, fields, stamp);
      } else if (eventType === "trade") {
        recorder.event("polynode", "confirmed_fill", eventType, fields, stamp);
      } else {
        recorder.event("polynode", "other", eventType, fields, stamp);
      }
    }
  });
  socket.on("error", (error) => {
    recorder.life("polynode", "error", { message: error.message });
    if (!resolved) {
      resolved = true;
      clearTimeout(timeout);
      rejectReady(error);
    }
  });
  socket.on("close", (code, reason) => recorder.life("polynode", "disconnected", { code, reason: reason.toString() }));

  return { ready, close: () => { try { socket.close(); } catch { /* noop */ } } };
}

async function fetchOrderFilledLogs(rpc: RpcClient, fromBlock: number, toBlock: number): Promise<ChainFill[]> {
  const queries: Array<{ version: "v1" | "v2"; addresses: string[]; topic: string }> = [
    { version: "v1", addresses: V1_EXCHANGES, topic: V1_ORDER_FILLED_TOPIC },
    { version: "v2", addresses: V2_EXCHANGES, topic: V2_ORDER_FILLED_TOPIC },
  ];
  const fills: ChainFill[] = [];
  for (const query of queries) {
    const logs = await rpc.call<JsonRpcLog[]>("eth_getLogs", [{
      fromBlock: hexBlock(fromBlock),
      toBlock: hexBlock(toBlock),
      address: query.addresses,
      topics: [query.topic],
    }]);
    for (const log of logs) {
      if (log.removed) continue;
      const txHash = normalizeHash(log.transactionHash);
      const logIndex = numeric(log.logIndex);
      const blockNumber = numeric(log.blockNumber);
      const address = normalizeHash(log.address);
      if (!txHash || logIndex == null || blockNumber == null || !address) continue;
      fills.push({
        tx_hash: txHash,
        log_index: logIndex,
        receipt_log_index: -1,
        block_number: blockNumber,
        block_hash: normalizeHash(log.blockHash) ?? "",
        address,
        order_hash: normalizeHash(log.topics?.[1]),
        version: query.version,
      });
    }
  }
  const unique = new Map<string, ChainFill>();
  for (const fill of fills) unique.set(`${fill.tx_hash}:${fill.log_index}`, fill);
  const ordered = [...unique.values()].sort((a, b) => a.block_number - b.block_number || a.log_index - b.log_index);

  const txHashes = [...new Set(ordered.map((fill) => fill.tx_hash))];
  const receipts = await rpc.batch<JsonRpcReceipt>(
    "eth_getTransactionReceipt",
    txHashes.map((hash) => [hash]),
  );
  const receiptsByHash = new Map<string, JsonRpcReceipt>();
  for (const receipt of receipts) {
    const hash = normalizeHash(receipt.transactionHash);
    if (hash) receiptsByHash.set(hash, receipt);
  }
  for (const fill of ordered) {
    const receipt = receiptsByHash.get(fill.tx_hash);
    const receiptIndex = receipt?.logs?.findIndex(
      (log) =>
        numeric(log.logIndex) === fill.log_index &&
        normalizeHash(log.address) === fill.address &&
        normalizeHash(log.topics?.[0]) === (fill.version === "v1" ? V1_ORDER_FILLED_TOPIC : V2_ORDER_FILLED_TOPIC),
    );
    if (receiptIndex == null || receiptIndex < 0) {
      throw new Error(`Could not resolve receipt-local log index for ${fill.tx_hash}:${fill.log_index}`);
    }
    fill.receipt_log_index = receiptIndex;
  }
  return ordered;
}

function canonicalizeStructFillIndexes(events: NormalizedEvent[], fills: ChainFill[]): Record<string, number> {
  const byReceiptIndex = new Map(
    fills.map((fill) => [`${fill.tx_hash}:${fill.receipt_log_index}`, fill]),
  );
  const byOrderHash = new Map<string, ChainFill[]>();
  for (const fill of fills) {
    if (!fill.order_hash) continue;
    const key = `${fill.tx_hash}:${fill.order_hash}`;
    const values = byOrderHash.get(key) ?? [];
    values.push(fill);
    byOrderHash.set(key, values);
  }

  const diagnostics = {
    eligible_struct_confirmed_records: 0,
    eligible_struct_orderfilled_events: 0,
    eligible_struct_ordersmatched_events: 0,
    mapped_by_receipt_log_index: 0,
    mapped_orderfilled_by_unique_order_hash_fallback: 0,
    mapped_ordersmatched_to_orderfilled_by_unique_order_hash: 0,
    unmatched: 0,
    index_order_hash_mismatches: 0,
  };
  const groundTruthTx = new Set(fills.map((fill) => fill.tx_hash));
  for (const event of events) {
    if (
      event.source !== "struct" ||
      event.path !== "confirmed" ||
      (event.trade_type !== "OrderFilled" && event.trade_type !== "OrdersMatched") ||
      !event.tx_hash ||
      !groundTruthTx.has(event.tx_hash)
    ) continue;
    diagnostics.eligible_struct_confirmed_records++;
    if (event.trade_type === "OrdersMatched") {
      diagnostics.eligible_struct_ordersmatched_events++;
      const orderMatches = event.order_hash ? byOrderHash.get(`${event.tx_hash}:${event.order_hash}`) : undefined;
      if (orderMatches?.length === 1) {
        event.canonical_log_index = orderMatches[0].log_index;
        diagnostics.mapped_ordersmatched_to_orderfilled_by_unique_order_hash++;
      } else {
        diagnostics.unmatched++;
      }
      continue;
    }

    diagnostics.eligible_struct_orderfilled_events++;
    const indexed = event.log_index == null ? undefined : byReceiptIndex.get(`${event.tx_hash}:${event.log_index}`);
    const indexedMatchesOrder =
      indexed != null &&
      (event.order_hash == null || indexed.order_hash == null || event.order_hash === indexed.order_hash);
    if (indexedMatchesOrder) {
      event.canonical_log_index = indexed.log_index;
      diagnostics.mapped_by_receipt_log_index++;
      continue;
    }
    if (indexed) diagnostics.index_order_hash_mismatches++;
    const orderMatches = event.order_hash ? byOrderHash.get(`${event.tx_hash}:${event.order_hash}`) : undefined;
    if (orderMatches?.length === 1) {
      event.canonical_log_index = orderMatches[0].log_index;
      diagnostics.mapped_orderfilled_by_unique_order_hash_fallback++;
    } else {
      diagnostics.unmatched++;
    }
  }
  return diagnostics;
}

async function dnsManifest(urls: Record<string, string>): Promise<Record<string, unknown>> {
  const result: Record<string, unknown> = {};
  for (const [name, value] of Object.entries(urls)) {
    const host = new URL(value).hostname;
    try {
      result[name] = { host, addresses: await lookup(host, { all: true }) };
    } catch (error) {
      result[name] = { host, error: errorText(error) };
    }
  }
  return result;
}

async function fileHash(path: string): Promise<string> {
  return createHash("sha256").update(await readFile(path)).digest("hex");
}

async function metadata(): Promise<{ harnessSourceCommit: string | null; sdkVersion: string | null }> {
  let harnessSourceCommit: string | null = /^[0-9a-f]{40}$/.test(process.env.BENCH_SOURCE_COMMIT ?? "")
    ? process.env.BENCH_SOURCE_COMMIT!
    : null;
  let sdkVersion: string | null = null;
  if (!harnessSourceCommit) {
    try {
      harnessSourceCommit = (await execFileAsync("git", ["rev-parse", "HEAD"])).stdout.trim();
    } catch { /* recorded as null */ }
  }
  try {
    const packageJson = JSON.parse(await readFile("node_modules/@structbuild/sdk/package.json", "utf8")) as { version?: string };
    sdkVersion = packageJson.version ?? null;
  } catch { /* recorded as null */ }
  return { harnessSourceCommit, sdkVersion };
}

async function writeArtifacts(
  outputDir: string,
  recorder: Recorder,
  rpc: RpcClient,
  chainFills: ChainFill[],
  manifest: Record<string, unknown>,
  analysisResult: ReturnType<typeof analyze>,
): Promise<void> {
  await recorder.finishRawFrames();
  manifest.collection_storage = {
    normalized_events_buffered_for_analysis: recorder.events.length,
    raw_frames_streamed_to_disk: recorder.rawFramesWritten,
    raw_frame_backpressure_writes: recorder.rawFrameBackpressureWrites,
  };
  const blockWindow = manifest.block_window as {
    from_block: number;
    to_block: number;
    from_block_hash?: string;
    to_block_hash?: string;
  };
  const { analysis, latencySamples } = analysisResult;
  await mkdir(outputDir, { recursive: true });
  const ndjson = (values: unknown[]) => values.map((value) => JSON.stringify(value)).join("\n") + "\n";
  await Promise.all([
    writeFile(resolve(outputDir, "events.ndjson"), ndjson(recorder.events)),
    writeFile(resolve(outputDir, "rpc_logs.json"), JSON.stringify({ calls: rpc.audit, order_filled_logs: chainFills }, null, 2) + "\n"),
    writeFile(resolve(outputDir, "latency_samples.csv"), latencySamplesCsv(latencySamples)),
    writeFile(resolve(outputDir, "missing.json"), JSON.stringify(analysis.missing, null, 2) + "\n"),
    writeFile(resolve(outputDir, "summary.json"), JSON.stringify(analysis, null, 2) + "\n"),
    writeFile(resolve(outputDir, "REPORT.md"), renderReport(analysis, manifest)),
  ]);
  const existingResources = isObject(manifest.runtime_resources) ? manifest.runtime_resources : {};
  manifest.runtime_resources = {
    ...existingResources,
    host_after_artifact_generation: await linuxMemorySnapshot(),
    collector_process_max_rss_kb: process.resourceUsage().maxRSS,
  };
  await writeFile(resolve(outputDir, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");
  const artifactNames = [
    "REPORT.md",
    "events.ndjson",
    "latency_samples.csv",
    "manifest.json",
    "missing.json",
    "raw_frames.ndjson",
    "rpc_logs.json",
    "summary.json",
  ];
  const checksums = await Promise.all(
    artifactNames.map(async (name) => `${await fileHash(resolve(outputDir, name))}  ${name}`),
  );
  await writeFile(resolve(outputDir, "SHA256SUMS"), `${checksums.join("\n")}\n`);

  console.log("\nCompleted independent on-chain audit:");
  console.log(`  blocks: ${blockWindow.from_block}-${blockWindow.to_block}`);
  console.log(`  ground truth: ${analysis.chain_ground_truth.transactions} tx / ${analysis.chain_ground_truth.fills} fills`);
  console.log(`  Struct: ${analysis.observations.struct_pending_events} pending / ${analysis.observations.struct_confirmed_events} confirmed events`);
  console.log(`  Polynode: ${analysis.observations.polynode_pending_events} pending / ${analysis.observations.polynode_status_update_events} status updates / ${analysis.observations.polynode_trade_events} fills`);
  console.log(`  RTDS: ${analysis.observations.rtds_activity_events} activity events`);
  console.log(`  artifacts: ${outputDir}`);
}

async function main(): Promise<void> {
  const args = parseArgs();
  const startedAt = new Date();
  const stamp = startedAt.toISOString().replaceAll(":", "-").replaceAll(".", "-");
  const outputDir = resolve(args.out ?? `results/${stamp}`);
  await mkdir(outputDir, { recursive: true });
  const recorder = new Recorder(resolve(outputDir, "raw_frames.ndjson"));
  const rpc = new RpcClient(args.polygonRpcUrl, recorder);
  const hostMemoryBefore = await linuxMemorySnapshot();
  recorder.life("benchmark", "started", { output_dir: outputDir });

  console.log(`Connecting ${args.includeStruct ? "Struct, " : ""}Polynode, and RTDS from one process...`);
  const rtds = connectRtds(args, recorder);
  const polynode = connectPolynode(args, recorder);
  const struct = args.includeStruct ? connectStruct(args, recorder) : undefined;
  try {
    const [structAck, polynodeAck, rtdsAck] = await Promise.all([
      struct?.ready ?? Promise.resolve(undefined),
      polynode.ready,
      rtds.ready,
    ]);
    recorder.life("benchmark", "all_subscribed");
    console.log(`All subscriptions active. Warming up for ${args.warmupSec}s...`);
    await sleep(args.warmupSec * 1_000);

    const startTip = await rpc.blockNumber();
    const fromBlock = startTip + 2;
    const coreStarted = now();
    recorder.life("benchmark", "ground_truth_window_armed", { start_tip: startTip, from_block: fromBlock });
    console.log(`Ground-truth window armed at future block ${fromBlock}; collecting for ${args.durationSec}s...`);
    await sleep(args.durationSec * 1_000);

    const endTip = await rpc.blockNumber();
    const toBlock = endTip - 2;
    if (toBlock < fromBlock) throw new Error(`Polygon advanced too few blocks (${fromBlock}-${toBlock})`);
    const coreEnded = now();
    recorder.life("benchmark", "ground_truth_window_closed", { end_tip: endTip, to_block: toBlock });
    console.log(`Window closed at block ${toBlock}. Keeping sockets open for a ${args.tailSec}s confirmation tail...`);
    await sleep(args.tailSec * 1_000);

    struct?.close();
    polynode.close();
    rtds.close();
    recorder.life("benchmark", "sockets_closed");

    const dnsEndpoints = {
      ...(args.includeStruct ? { struct: args.structWsBase } : {}),
      polynode: args.polynodeWsUrl,
      rtds: args.rtdsUrl,
      polygon_rpc: args.polygonRpcUrl,
    };
    const [fromAnchor, toAnchor, chainFills, dns, meta] = await Promise.all([
      rpc.call<Record<string, unknown>>("eth_getBlockByNumber", [hexBlock(fromBlock), false]),
      rpc.call<Record<string, unknown>>("eth_getBlockByNumber", [hexBlock(toBlock), false]),
      fetchOrderFilledLogs(rpc, fromBlock, toBlock),
      dnsManifest(dnsEndpoints),
      metadata(),
    ]);
    const structFillIndexReconciliation = canonicalizeStructFillIndexes(recorder.events, chainFills);
    const fromHash = normalizeHash(fromAnchor.hash);
    const toHash = normalizeHash(toAnchor.hash);
    if (!fromHash || !toHash) throw new Error(`Polygon boundary anchors are missing for ${fromBlock}-${toBlock}`);
    const analysisResult = analyze(recorder.events, chainFills, {
      from_block: fromBlock,
      to_block: toBlock,
      from_block_hash: fromHash,
      to_block_hash: toHash,
    });
    const analysisCompletedAt = new Date().toISOString();
    const [fromAnchorRecheck, toAnchorRecheck] = await Promise.all([
      rpc.call<Record<string, unknown>>("eth_getBlockByNumber", [hexBlock(fromBlock), false]),
      rpc.call<Record<string, unknown>>("eth_getBlockByNumber", [hexBlock(toBlock), false]),
    ]);
    const fromHashRecheck = normalizeHash(fromAnchorRecheck.hash);
    const toHashRecheck = normalizeHash(toAnchorRecheck.hash);
    if (!fromHash || !toHash || fromHash !== fromHashRecheck || toHash !== toHashRecheck) {
      throw new Error(`Polygon boundary hash recheck failed for ${fromBlock}-${toBlock}`);
    }
    const boundaryRecheckedAt = new Date().toISOString();
    const indexPath = new URL(import.meta.url).pathname;
    const analysisPath = new URL("./analysis.ts", import.meta.url).pathname;
    const manifest: Record<string, unknown> = {
      schema_version: 1,
      generated_at: new Date().toISOString(),
      benchmark_started_at: startedAt.toISOString(),
      provenance: {
        upstream_repository: "https://github.com/structbuild/polymarket-rtds-vs-struct-benchmark",
        upstream_commit: "4df16e1c2c6a8b51728842b8031d027382910dd0",
        harness_source_commit: meta.harnessSourceCommit,
        source_tree_state: process.env.BENCH_SOURCE_TREE_STATE ?? "unknown",
        harness_note: "Extended from Struct's published harness with Polynode and independent Polygon log truth.",
        index_ts_sha256: await fileHash(indexPath),
        analysis_ts_sha256: await fileHash(analysisPath),
      },
      runtime: {
        node: process.version,
        struct_sdk: meta.sdkVersion,
        platform: platform(),
        arch: arch(),
        hostname: hostname(),
        timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      },
      runtime_resources: {
        host_before_collection: hostMemoryBefore,
      },
      clock: {
        arrival_clock: "process.hrtime.bigint()",
        resolution: "nanoseconds represented as decimal strings",
        wall_clock: "Date.now() retained only for audit; latency uses monotonic clock",
        single_process: true,
      },
      endpoints: {
        struct: safeUrl(args.structWsBase),
        polynode: safeUrl(args.polynodeWsUrl),
        rtds: safeUrl(args.rtdsUrl),
        polygon_rpc: safeUrl(args.polygonRpcUrl),
      },
      credential_fingerprints: {
        ...(args.includeStruct ? { struct: fingerprint(args.structApiKey) } : {}),
        polynode: fingerprint(args.polynodeApiKey),
        polygon_rpc: fingerprint(args.polygonRpcUrl),
      },
      config: {
        duration_sec: args.durationSec,
        warmup_sec: args.warmupSec,
        confirmation_tail_sec: args.tailSec,
        boundary_guard_blocks: 2,
        struct_status: args.structStatus,
        struct_trade_types: args.tradeTypes ?? "unfiltered",
        rtds_heartbeat: args.rtdsHeartbeat,
        rtds_silence_reconnect_sec: args.rtdsSilenceReconnectSec,
        include_struct: args.includeStruct,
      },
      subscriptions: {
        struct: args.includeStruct && struct ? {
          room: "polymarket_trades",
          requested: { status: args.structStatus, subscribe_all: true, ...(args.tradeTypes?.length ? { trade_types: args.tradeTypes } : {}) },
          acknowledged: structAck,
          transport: "raw_websocket_callback_stamped_before_json_parse",
        } : { enabled: false },
        polynode: { requested: { action: "subscribe", type: "trades" }, acknowledged: polynodeAck },
        rtds: rtdsAck,
      },
      block_window: {
        from_block: fromBlock,
        to_block: toBlock,
        from_block_hash: fromHash,
        to_block_hash: toHash,
        start_tip: startTip,
        end_tip: endTip,
        boundary_hash_recheck: {
          from_block_hash: fromHashRecheck,
          to_block_hash: toHashRecheck,
          matched: true,
        },
      },
      collection_timeline: {
        core_started_mono_ns: coreStarted.monoNs,
        core_started_wall_ms: coreStarted.wallMs,
        core_ended_mono_ns: coreEnded.monoNs,
        core_ended_wall_ms: coreEnded.wallMs,
        analysis_completed_at: analysisCompletedAt,
        boundary_rechecked_at: boundaryRecheckedAt,
      },
      polygon_scope: {
        contract_source: "https://docs.polymarket.com/resources/contracts",
        v1_exchanges: V1_EXCHANGES,
        v1_order_filled_topic: V1_ORDER_FILLED_TOPIC,
        v2_exchanges: V2_EXCHANGES,
        v2_order_filled_topic: V2_ORDER_FILLED_TOPIC,
      },
      struct_fill_index_reconciliation: structFillIndexReconciliation,
      dns,
      lifecycle: recorder.lifecycle,
      rpc_audit: rpc.audit,
    };
    await writeArtifacts(outputDir, recorder, rpc, chainFills, manifest, analysisResult);
  } finally {
    try { struct?.close(); } catch { /* noop */ }
    try { polynode.close(); } catch { /* noop */ }
    try { rtds.close(); } catch { /* noop */ }
    try { await recorder.finishRawFrames(); } catch (error) {
      console.error(`raw frame stream close failed: ${errorText(error)}`);
    }
  }
}

main().catch((error) => {
  console.error(errorText(error));
  process.exitCode = 1;
});

