{
  "name": "polymarket-rtds-vs-struct-benchmark",
  "version": "1.0.0",
  "description": "Race Polymarket's public RTDS feed against the Struct Trades WebSocket and measure the latency, coverage, and mempool reliability difference.",
  "type": "module",
  "license": "MIT",
  "scripts": {
    "start": "tsx index.ts",
    "bench": "tsx index.ts",
    "aggregate": "tsx aggregate.ts",
    "check": "tsc --noEmit",
    "test": "tsx --test analysis.test.ts"
  },
  "dependencies": {
    "@structbuild/sdk": "^0.6.7",
    "ws": "^8.18.0"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "@types/ws": "^8.5.13",
    "tsx": "^4.19.0",
    "typescript": "^5.7.0"
  },
  "engines": {
    "node": ">=20"
  }
}
